def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Endgame: always defect on last round
    if n == 99:
        return 'D'

    # Compute statistics
    opp_def = sum(1 for h in history if h[1] == 'D')
    my_def = sum(1 for h in history if h[0] == 'D')
    opp_last = history[-1][1]
    my_last = history[-1][0]

    # If opponent is mostly defecting, defect
    if opp_def > n * 0.5:
        return 'D'

    # If we have defected many times and opponent never retaliated, they are likely pure cooperator
    if opp_def == 0 and my_def > 3:
        return 'D'

    # If opponent just defected
    if opp_last == 'D':
        # If opponent has been mostly cooperative, forgive sometimes
        if opp_def <= n * 0.25:
            if rng.random() < 0.4:
                return 'C'
        return 'D'

    # Opponent cooperated last round.
    # Compute forgiveness rate: how often opponent cooperated after our defection
    my_def_idx = []
    for i in range(n):
        if history[i][0] == 'D':
            my_def_idx.append(i)
    if my_def_idx:
        coop_after = 0
        total = 0
        for i in my_def_idx:
            if i + 1 < n:
                total += 1
                if history[i+1][1] == 'C':
                    coop_after += 1
        forgiveness = coop_after / total if total > 0 else 0.5
    else:
        forgiveness = 0.5

    # If opponent is very cooperative and forgiving, exploit
    if opp_def <= max(1, n * 0.1) and forgiveness > 0.7:
        if rng.random() < 0.8:
            return 'D'
        return 'C'

    # If opponent is very cooperative, gradually start testing
    if opp_def <= max(1, n * 0.1):
        if my_last == 'C' and (my_def == 0 or forgiveness > 0.3):
            if n < 10:
                return 'C'
            if n < 20:
                if rng.random() < 0.2:
                    return 'D'
            elif n < 40:
                if rng.random() < 0.5:
                    return 'D'
            else:
                if rng.random() < 0.8:
                    return 'D'
        return 'C'

    # If opponent rarely defects, occasionally test
    if opp_def <= n * 0.1:
        if my_last == 'C' and rng.random() < 0.1:
            return 'D'
        return 'C'

    # Default: cooperate
    return 'C'
